/**
 *  A single MCP server declared in `config.toml`. We only surface the name and
 *  launch command — never secrets like `env` blocks or headers.
 */
export type McpServerInfo = {
	name: string,
	command: string | null,
};

/**
 *  One MCP server as the edit form describes it.
 * 
 *  Transport is chosen by which fields are populated, matching Codex's own
 *  config shape: a `command` means stdio, a `url` means streamable HTTP.
 */
export type McpServerInput = {
	/**
	 *  The name the server is currently stored under. `None` adds a new server;
	 *  `Some` edits that entry, which is also how a rename is expressed.
	 */
	previousName?: string | null,
	name: string,
	command?: string | null,
	args?: string[],
	/**  Newly typed secret values only; see `env_keys`. */
	env?: { [key in string]: string },
	/**
	 *  Full desired set of env variable names; see `upsert_stdio_server`. Absent
	 *  means "leave the stored env table alone".
	 */
	envKeys?: string[] | null,
	url?: string | null,
	bearerTokenEnvVar?: string | null,
};

export type McpServerParams = {
	threadId?: string | null,
	name?: string | null,
	serverName?: string | null,
};

/**
 *  Redacted view of one `[mcp_servers.<name>]` entry. Never carries secret
 *  values — only the names of environment variables / bearer tokens.
 */
export type McpServerSummary = {
	name: string,
	/**  `"stdio"`, `"http"`, or `"unknown"` for malformed entries. */
	transport: string,
	command: string | null,
	/**
	 *  The stdio `args` array verbatim. Not secret, and the edit form needs the
	 *  real values to round-trip a "Configure" without dropping them.
	 */
	args: string[],
	url: string | null,
	/**  Names of `env` keys defined for a stdio server (values redacted). */
	envKeys: string[],
	/**  Name of the `bearer_token_env_var` for an HTTP server, if any. */
	bearerTokenEnvVar: string | null,
	enabled: boolean,
	/**  MCP servers configured in `config.toml` are global to this Codex home. */
	scope: string,
};

